-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE return_request (id BIGSERIAL PRIMARY KEY, return_key VARCHAR(128) NOT NULL UNIQUE, order_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, reason VARCHAR(255) NOT NULL, refundable_amount NUMERIC(19,2) NOT NULL, receiving_warehouse_id BIGINT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE return_line (id BIGSERIAL PRIMARY KEY, return_id BIGINT NOT NULL REFERENCES return_request(id), order_line_id BIGINT NOT NULL, seller_id BIGINT NOT NULL, sku_id BIGINT NOT NULL, quantity INT NOT NULL, refundable_amount NUMERIC(19,2) NOT NULL, inspection_status VARCHAR(32) NULL, UNIQUE(return_id, order_line_id));
CREATE TABLE inbox_event (id BIGSERIAL PRIMARY KEY, consumer_name VARCHAR(128) NOT NULL, event_id VARCHAR(36) NOT NULL, processed_at TIMESTAMP NOT NULL, UNIQUE(consumer_name,event_id));
CREATE TABLE outbox_event (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(36) NOT NULL UNIQUE, aggregate_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);
